// ShakaPlayer.js
import React, { useEffect, useRef } from "react";
import shaka from "shaka-player/dist/shaka-player.ui.js";
import "shaka-player/dist/controls.css";

// Manifest gerado pela sua API
const MANIFEST_URL =
  "http://localhost:5000/videos/user_123/938b3031-ac2f-4007-9fc0-d8111a476061/manifest.mpd";

function ShakaPlayer() {
  const videoRef = useRef(null);
  const containerRef = useRef(null);
  const didInitRef = useRef(false); // evita init duplo em dev

  useEffect(() => {

    if (didInitRef.current) {
      console.log("ShakaPlayer: já inicializado, ignorando novo useEffect");
      return;
    }
    didInitRef.current = true;

    shaka.polyfill.installAll();

    if (!shaka.Player.isBrowserSupported()) {
      console.error("Navegador não suportado pelo Shaka");
      return;
    }

    const video = videoRef.current;
    const container = containerRef.current;
    if (!video || !container) {
      console.error("ShakaPlayer: video ou container null");
      return;
    }

    const player = new shaka.Player();
    const ui = new shaka.ui.Overlay(player, container, video);

    const onShakaError = (event) => {
      console.error("Shaka error event:", event.detail);
    };
    player.addEventListener("error", onShakaError);

    const onVideoError = (event) => {
      console.error("HTML5 video error:", event);
    };
    video.addEventListener("error", onVideoError);

    player
      .attach(video)
      .then(() => {
        console.log("Player anexado ao <video>");
        return player.load(MANIFEST_URL);
      })
      .then(() => {
        console.log("Manifest carregado com sucesso!");
      })
      .catch((error) => {
        console.error(
          "Erro ao carregar o manifest via load(): code=",
          error.code,
          "category=",
          error.category,
          "data=",
          error.data
        );
      });

    return () => {
      console.log("ShakaPlayer: cleanup");
      video.removeEventListener("error", onVideoError);
      player.removeEventListener("error", onShakaError);
      ui.destroy();
      player.destroy();
    };
  }, []); // importante: []

  return (
    <div style={{ maxWidth: "960px", margin: "0 auto", padding: "1rem" }}>
      <h1>Player DASH (Shaka)</h1>

      <div ref={containerRef} style={{ width: "100%" }}>
        <video
          ref={videoRef}
          width={960}
          height={540}
          autoPlay
          controls
          style={{ width: "100%" }}
        />
      </div>

      <p style={{ marginTop: "1rem" }}>
        Manifest atual: <code>{MANIFEST_URL}</code>
      </p>
    </div>
  );
}

export default ShakaPlayer;


